const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const TARGET=process.env.TARGET_FILE,PARENT=process.env.PARENT_SHA,TARGET_SHA=process.env.TARGET_SHA,PARENT_BLOB=process.env.PARENT_BLOB,TARGET_BLOB=process.env.TARGET_BLOB,HASH=process.env.TARGET_HASH,BYTES=Number(process.env.TARGET_BYTES),assert=(x,m)=>{if(!x)throw new Error(m)},sh=c=>cp.execSync(c,{encoding:'utf8'}).trim();
const SEL='body.home-index-shell .professional-showcase > .professional-showcase__rail > .professional-showcase__track';
function parse(src){const ls=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<ls.length;i++){const line=ls[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[]}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t]}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context})}}depth+=o-c;while(stack.length&&depth<=stack.at(-1).depthBefore){const p=stack.pop();if(p.type==='rule')sel=null}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d)}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)}}
assert(sh('git rev-parse HEAD')===TARGET_SHA,'wrong target SHA');assert(sh(`git rev-parse ${PARENT}:${TARGET}`)===PARENT_BLOB,'parent blob drift');assert(sh(`git hash-object ${TARGET}`)===TARGET_BLOB,'target blob drift');const parent=cp.execFileSync('git',['show',`${PARENT}:${TARGET}`],{encoding:'utf8'}),pp=parse(parent);assert(pp.declarations.length===214&&pp.dead.length===1,`parent parse drift ${pp.declarations.length}/${pp.dead.length}`);const d=pp.dead[0];assert(d.line===323&&d.selector===SEL&&d.property==='gap'&&d.value==='14px'&&!d.important,'parent dead row drift');assert(d.context.includes('@media (max-width: 760px)'),'parent context drift');assert(d.winnerLine===366&&d.winnerValue==='var(--professional-showcase-gap)'&&!d.winnerImportant,'parent winner drift');const nl=/\r?\n$/.test(parent),ls=parent.split(/\r?\n/);if(nl&&ls.at(-1)==='')ls.pop();assert(ls[d.line-1]?.trim()==='gap: 14px;','parent source mismatch');ls.splice(d.line-1,1);const reconstructed=Buffer.from(ls.join('\n')+(nl?'\n':''));const target=fs.readFileSync(TARGET),tp=parse(target.toString('utf8')),hash=crypto.createHash('sha256').update(target).digest('hex');assert(tp.declarations.length===213&&tp.dead.length===0,`target parse drift ${tp.declarations.length}/${tp.dead.length}`);assert(Buffer.compare(reconstructed,target)===0,'independent reconstruction is not byte-identical');assert(hash===HASH&&target.length===BYTES,`target identity drift ${hash}/${target.length}`);console.log(`CERT IDENTITY PASS|sha=${TARGET_SHA}|parent=${PARENT}|parentBlob=${PARENT_BLOB}|targetBlob=${TARGET_BLOB}|hash=${hash}|bytes=${target.length}|decl=214->213|dead=1->0|files=1|additions=0|deletions=1|transport=independent-byte-reconstruction`);
